import{_ as r,c as o,o as n,j as a,Y as s,t as i}from"./chunks/framework.D-NV0Bun.js";const u=JSON.parse('{"title":"rm | x-cmd man (man1) | remove files or directories","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | rm - remove files or directories","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"rm | x-cmd man (man1) | remove files or directories"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | rm - remove files or directories"}]]},"headers":[],"params":{"isMan":true,"man":"rm","category":"man1","desc":"remove files or directories"},"relativePath":"man1/rm.md","filePath":"man1/[man].md"}'),d={name:"man1/rm.md"},m={class:"visually-hidden"};function l(t,e,g,h,c,p){return n(),o("div",null,[a("h1",m,i(t.$params.man),1),e[0]||(e[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>rm - remove files or directories</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>rm</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This manual page documents the GNU version of <strong>rm</strong>. <strong>rm</strong> removes each specified file. By default, it does not remove directories.</p><p>If the <em>-I</em> or <em>--interactive=once</em> option is given, and there are more than three files or the <em>-r</em>, <em>-R</em>, or <em>--recursive</em> are given, then <strong>rm</strong> prompts the user for whether to proceed with the entire operation. If the response is not affirmative, the entire command is aborted.</p><p>Otherwise, if a file is unwritable, standard input is a terminal, and the <em>-f</em> or <em>--force</em> option is not given, or the <em>-i</em> or <em>--interactive=always</em> option is given, <strong>rm</strong> prompts the user for whether to remove the file. If the response is not affirmative, the file is skipped.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>Remove (unlink) the FILE(s).</p><dl><dt><strong>-f</strong>, <strong>--force</strong></dt><dd>ignore nonexistent files and arguments, never prompt</dd><dt><strong>-i</strong></dt><dd>prompt before every removal</dd><dt><strong>-I</strong></dt><dd>prompt once before removing more than three files, or when removing recursively; less intrusive than <strong>-i</strong>, while still giving protection against most mistakes</dd><dt><strong>--interactive</strong>[=<em>WHEN</em>]</dt><dd>prompt according to WHEN: never, once (<strong>-I</strong>), or always (<strong>-i</strong>); without WHEN, prompt always</dd><dt><strong>--one-file-system</strong></dt><dd>when removing a hierarchy recursively, skip any directory that is on a file system different from that of the corresponding command line argument</dd><dt><strong>--no-preserve-root</strong></dt><dd>do not treat &#39;/&#39; specially</dd><dt><strong>--preserve-root</strong>[=<em>all</em>]</dt><dd>do not remove &#39;/&#39; (default); with &#39;all&#39;, reject any command line argument on a separate device from its parent</dd><dt><strong>-r</strong>, <strong>-R</strong>, <strong>--recursive</strong></dt><dd>remove directories and their contents recursively</dd><dt><strong>-d</strong>, <strong>--dir</strong></dt><dd>remove empty directories</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>explain what is being done</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>By default, rm does not remove directories. Use the <strong>--recursive</strong> (<strong>-r</strong> or <strong>-R</strong>) option to remove each listed directory, too, along with all of its contents.</p><p>To remove a file whose name starts with a &#39;-&#39;, for example &#39;-foo&#39;, use one of these commands:</p><blockquote><p>rm <strong>--</strong> <strong>-foo</strong></p></blockquote><blockquote><p>rm ./-foo</p></blockquote><p>Note that if you use rm to remove a file, it might be possible to recover some of its contents, given sufficient expertise and/or time. For greater assurance that the contents are truly unrecoverable, consider using <strong>shred</strong>(1).</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Paul Rubin, David MacKenzie, Richard M. Stallman, and Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>unlink</strong>(1), <strong>unlink</strong>(2), <strong>chattr</strong>(1), <strong>shred</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/rm%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/rm\\</a>&gt; <br> or available locally via: info &#39;(coreutils) rm invocation&#39;</p>',25))])}const v=r(d,[["render",l]]);export{u as __pageData,v as default};
